mapper.update:
update dish_info
dishName = #{dishName,jdbcType=VARCHAR}, chefName = #{chefName,jdbcType=VARCHAR}, dishPrice = #{dishPrice,jdbcType=DECIMAL}, dishTypeId = #{dishTypeId,jdbcType=INTEGER}, dishDesc = #{dishDesc,jdbcType=VARCHAR}, isReserved = #{isReserved,jdbcType=TINYINT}, dishImg = #{dishImg,jdbcType=VARCHAR}, kitchenName = #{kitchenName,jdbcType=VARCHAR}, stockQty = #{stockQty,jdbcType=INTEGER}, isAvailable = #{isAvailable,jdbcType=TINYINT}, prepMinutes = #{prepMinutes,jdbcType=INTEGER}, spiceLevel = #{spiceLevel,jdbcType=TINYINT}, allergens = #{allergens,jdbcType=VARCHAR}, caloriesKcal = #{caloriesKcal,jdbcType=DECIMAL}, proteinG = #{proteinG,jdbcType=DECIMAL}, fatG = #{fatG,jdbcType=DECIMAL}, carbG = #{carbG,jdbcType=DECIMAL},
where dishId = #{dishId,jdbcType=INTEGER}

mapper.select:
select dishId, dishName, chefName,dishPrice, dishTypeId, dishDesc,isReserved, dishImg, kitchenName, stockQty, isAvailable, prepMinutes, spiceLevel, allergens, caloriesKcal, proteinG, fatG, carbG, createdAt, updatedAt, (select dishTypeName from dish_type where dish_type.dishTypeId = dish_info.dishTypeId) as dishTypeName from dish_info
and dishName like concat('%',#{dishName},'%')
and chefName like concat('%',#{chefName},'%')
and dishTypeId = #{dishTypeId}
limit #{begin}, #{size}

select dishId, dishName, chefName,dishPrice, dishTypeId, dishDesc,isReserved, dishImg, kitchenName, stockQty, isAvailable, prepMinutes, spiceLevel, allergens, caloriesKcal, proteinG, fatG, carbG, createdAt, updatedAt, (select dishTypeName from dish_type where dish_type.dishTypeId = dish_info.dishTypeId) as dishTypeName from dish_info
and dishTypeId = #{dishTypeId}
limit #{begin}, #{size}
